package com.sumedha.commerce.user.exception;
import com.sumedha.commerce.common.core.exception.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class GlobalExceptionHandlerTest {private final GlobalExceptionHandler handler=new GlobalExceptionHandler();@Test void mapsCommerceExceptions(){assertEquals(400,handler.commerce(new BadRequestException("bad")).getStatusCode().value());assertEquals(404,handler.commerce(new ResourceNotFoundException("missing")).getStatusCode().value());assertEquals(409,handler.commerce(new ConflictException("duplicate")).getStatusCode().value());assertEquals(500,handler.commerce(new InternalServerException("internal")).getStatusCode().value());}@Test void sanitizesBadAndUnexpectedErrors(){assertEquals(400,handler.bad(new RuntimeException("bad")).getStatusCode().value());var response=handler.error(new IllegalStateException("SQL secret"));assertEquals(500,response.getStatusCode().value());assertEquals("An unexpected error occurred",response.getBody().getMessage());assertFalse(response.getBody().getMessage().contains("IllegalState"));}}
